// Comprueba que llegó un archivo con contenido y en un formato que sabemos leer.
const bin = $input.item.binary?.archivo;
const meta = $json.archivo || {};
const nombre = String(bin?.fileName || meta.filename || 'documento');
const ext = nombre.includes('.') ? nombre.split('.').pop().toLowerCase() : '';
const tam = Number(meta.size ?? 0);
let error = '';
if (!bin) error = 'No llegó ningún archivo.';
else if (!tam) error = 'El archivo está vacío (0 bytes).';
else if (ext === 'doc') error = 'Los .doc antiguos no se pueden leer. Guárdalo como .docx o PDF y vuelve a subirlo.';
else if (!['pdf', 'docx', 'txt'].includes(ext)) error = `Formato no soportado${ext ? ' (.' + ext + ')' : ''}. Sube un PDF, DOCX o TXT.`;
else if (tam > 15 * 1024 * 1024) error = 'El archivo pasa de 15 MB.';
const out = { json: { archivo_nombre: nombre, formato: error ? 'error' : ext, error, tamano: tam,
  tipo: String($json.tipo || 'General'), interes: String($json.interes || '').trim().slice(0, 500) } };
// Un .docx es un zip: se marca como tal para poder descomprimirlo.
if (bin) out.binary = { archivo: ext === 'docx' ? { ...bin, fileExtension: 'zip' } : bin };
return out;

// Saca el texto de word/document.xml: un párrafo por línea.
const bins = $input.first().binary || {};
const clave = Object.keys(bins).find(k => ((bins[k].directory ? bins[k].directory + '/' : '') + bins[k].fileName).endsWith('word/document.xml'))
  || Object.keys(bins).find(k => bins[k].fileName === 'document.xml');
if ($input.first().json.error || !clave) return [{ json: { fallo: 'No se pudo abrir el DOCX (puede estar dañado o no ser un Word real).' } }];
const xml = (await this.helpers.getBinaryDataBuffer(0, clave)).toString('utf8');
const texto = xml.replace(/<w:tab\/>/g, '\t').replace(/<w:br[^>]*\/>/g, '\n').replace(/<\/w:p>/g, '\n').replace(/<[^>]+>/g, '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
return [{ json: { texto } }];

// Lee el TXT en UTF-8; si trae caracteres raros, prueba Latin-1 (archivos de Windows antiguos).
const buf = await this.helpers.getBinaryDataBuffer(0, 'archivo');
let texto = buf.toString('utf8');
if (texto.includes('�')) texto = buf.toString('latin1');
return [{ json: { texto: texto.replace(/^﻿/, '') } }];

// Limpia el texto, detecta escaneados y lo trocea si es largo.
const a = $('Revisar archivo').first().json;
const j = $input.first().json;
let error = j.fallo || '';
if (!error && a.formato === 'pdf' && typeof j.text !== 'string') error = 'No se pudo abrir el PDF (puede estar dañado o protegido con contraseña).';
const texto = String(j.texto ?? j.text ?? '').replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim();
const paginas = Number(j.numpages) || null;
const letras = (texto.match(/[\p{L}\p{N}]/gu) || []).length;
if (!error && a.formato === 'pdf' && letras < Math.max(50, 25 * (paginas || 1)))
  error = 'El PDF parece escaneado: es una imagen y no tiene texto que leer. Pásale un OCR o sube el documento original.';
if (!error && letras < 20) error = 'El documento no tiene texto que leer.';
if (error) return [{ json: { ...a, error, ok: false } }];
const base = { ...a, ok: true, paginas, caracteres: texto.length };
if (texto.length <= 12000) return [{ json: { ...base, modo: 'directo', partes: 1, texto_analisis: texto, completo: texto } }];
// Trozos de ~8000 caracteres, cortando en un salto de párrafo cuando se puede.
const trozos = []; let resto = texto;
while (resto.length && trozos.length < 10) {
  let corte = resto.length <= 8000 ? resto.length : resto.lastIndexOf('\n', 8000);
  if (corte < 8000 * 0.5) corte = Math.min(8000, resto.length);
  trozos.push(resto.slice(0, corte)); resto = resto.slice(corte).trim();
}
const recortado = resto.length > 0;
return trozos.map((t, i) => ({ json: { ...base, modo: 'partes', parte: i + 1, partes: trozos.length, recortado, trozo: t, completo: i === 0 ? texto : '' } }));

// Junta los resúmenes de cada parte en orden. Si la IA falló en una parte, usa el inicio del texto original.
const trozos = $('Preparar texto').all();
const partes = $input.all().map((it, i) => {
  const r = String(it.json.text || '').trim();
  return `### Parte ${i + 1} de ${trozos.length}\n` + (r || trozos[i].json.trozo.slice(0, 1500) + ' […]');
});
const base = { ...trozos[0].json }; delete base.trozo;
return [{ json: { ...base, texto_analisis: partes.join('\n\n') } }];

