// Junta la respuesta de la IA (o reglas simples si falla) y prepara la pantalla, el Telegram y la fila.
const base = $('Preparar texto').first().json;
const texto = base.completo;
const meta = { ...base, ...($('Unir partes').isExecuted ? $('Unir partes').first().json : {}) };
let ia = null;
try { ia = JSON.parse(String($input.first().json.text || '').replace(/```(json)?/g, '').match(/\{[\s\S]*\}/)[0]); } catch {}
const lista = (v, n) => (Array.isArray(v) ? v : []).map(x => typeof x === 'string' ? x.trim() : x).filter(Boolean).slice(0, n);
// Respaldo por reglas: frases, fechas, importes y cláusulas típicas.
const reglas = () => {
  const frases = texto.replace(/\s+/g, ' ').split(/(?<=[.!?])\s+/).filter(f => f.length > 40);
  const MES = '(?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)';
  const fechas = [...new Set(texto.match(new RegExp(`\\b\\d{1,2}[/.-]\\d{1,2}[/.-]\\d{2,4}\\b|\\b\\d{1,2} de ${MES}(?: de \\d{4})?`, 'gi')) || [])];
  const importes = [...new Set(texto.match(/(?:€|\$|USD|EUR)\s?\d[\d.,]*|\d[\d.,]*\s?(?:€|euros?|EUR|USD|d[oó]lares)/gi) || [])];
  const lineas = texto.split(/\n+/).map(l => l.trim()).filter(Boolean);
  const riesgos = lineas.filter(l => /penaliz|indemniz|rescisi|resoluci[oó]n|renovaci|exclusiv|confidencial|demora|responsabilidad|preaviso/i.test(l));
  return { tipo_detectado: 'otro', titulo: base.archivo_nombre, resumen: frases.slice(0, 5), puntos_clave: lineas.filter(l => l.length < 90 && /^[\dIVX]+[.)]|^[A-ZÁÉÍÓÚÑ ]{6,}$/.test(l)).slice(0, 8),
    fechas: fechas.slice(0, 10).map(f => ({ fecha: f, que: '' })), importes: importes.slice(0, 10).map(i => ({ importe: i, concepto: '' })),
    riesgos: riesgos.slice(0, 8).map(r => r.slice(0, 220)), preguntas: ['¿Hay algo de este documento que no se haya revisado con un profesional?'] };
};
const r = ia && Array.isArray(ia.resumen) ? ia : reglas();
const res = {
  tipo_detectado: String(r.tipo_detectado || 'otro'), titulo: String(r.titulo || base.archivo_nombre).slice(0, 150),
  resumen: lista(r.resumen, 5), puntos_clave: lista(r.puntos_clave, 8),
  fechas: lista(r.fechas, 10).map(f => typeof f === 'string' ? { fecha: f, que: '' } : { fecha: String(f.fecha || ''), que: String(f.que || '') }),
  importes: lista(r.importes, 10).map(f => typeof f === 'string' ? { importe: f, concepto: '' } : { importe: String(f.importe || ''), concepto: String(f.concepto || '') }),
  riesgos: lista(r.riesgos, 8), preguntas: lista(r.preguntas, 6),
};
const origen = ia && Array.isArray(ia.resumen) ? 'ia' : 'reglas';
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const datos = [base.formato.toUpperCase(), base.paginas ? base.paginas + ' pág.' : '', base.caracteres.toLocaleString('es-ES') + ' caracteres',
  meta.partes > 1 ? `leído en ${meta.partes} partes${meta.recortado ? ' (recortado)' : ''}` : '', origen === 'ia' ? 'analizado con IA' : 'IA no disponible: análisis por reglas'].filter(Boolean).join(' · ');

// Pantalla final (sin saltos de línea: el formulario los respeta).
const ul = (xs, tag = 'ul') => xs.length ? `<${tag}>${xs.map(x => `<li>${esc(x)}</li>`).join('')}</${tag}>` : '<p><i>Nada detectado.</i></p>';
const tabla = (xs, a, b) => xs.length ? `<table>${xs.map(x => `<tr><td><b>${esc(x[a])}</b></td><td>${esc(x[b])}</td></tr>`).join('')}</table>` : '<p><i>Nada detectado.</i></p>';
const html = `<p><i>${esc(datos)}</i></p>` +
  `<h3>Resumen</h3>${ul(res.resumen)}<h3>Puntos clave</h3>${ul(res.puntos_clave)}` +
  `<h3>Fechas y plazos</h3>${tabla(res.fechas, 'fecha', 'que')}<h3>Importes</h3>${tabla(res.importes, 'importe', 'concepto')}` +
  `<h3>Riesgos y consideraciones</h3>${ul(res.riesgos)}<h3>Preguntas recomendadas</h3>${ul(res.preguntas, 'ol')}`;

// Telegram: por líneas, cortando antes de 3800 caracteres para no partir etiquetas.
const L = [`📄 <b>${esc(res.titulo)}</b>`, `<i>${esc(base.archivo_nombre)} · ${esc(datos)}</i>`];
const bloque = (t, xs) => { if (xs.length) L.push('', `<b>${t}</b>`, ...xs); };
bloque('Resumen', res.resumen.map(x => '• ' + esc(x)));
bloque('Fechas', res.fechas.map(f => `• ${esc(f.fecha)}${f.que ? ' — ' + esc(f.que) : ''}`));
bloque('Importes', res.importes.map(f => `• ${esc(f.importe)}${f.concepto ? ' — ' + esc(f.concepto) : ''}`));
bloque('Riesgos', res.riesgos.map(x => '⚠️ ' + esc(x)));
bloque('Preguntas', res.preguntas.map(x => '❓ ' + esc(x)));
bloque('Puntos clave', res.puntos_clave.map(x => '• ' + esc(x)));
let telegram = '';
for (const l of L) { if ((telegram + l).length > 3800) { telegram += '\n… (completo en la tabla documentos_leidos)'; break; } telegram += (telegram ? '\n' : '') + l; }

const fila = { fecha: $now.toISO(), archivo: base.archivo_nombre, formato: base.formato, tipo_indicado: base.tipo, tipo_detectado: res.tipo_detectado,
  titulo: res.titulo, interes: base.interes, paginas: base.paginas, caracteres: base.caracteres, partes: meta.partes || 1,
  resumen: res.resumen.join('\n'), puntos_clave: res.puntos_clave.join('\n'), fechas: res.fechas.map(f => f.fecha + (f.que ? ' — ' + f.que : '')).join('\n'),
  importes: res.importes.map(f => f.importe + (f.concepto ? ' — ' + f.concepto : '')).join('\n'), riesgos: res.riesgos.join('\n'), preguntas: res.preguntas.join('\n'), origen };
return [{ json: { fila, html, telegram, titulo: res.titulo } }];

