.container { width: min(760px, 94vw); }
.card { text-align: left; }
.card h1, .card h2, .card h3 { text-align: left; }
.card h3 { margin: 18px 0 6px; font-size: 16px; }
.card p, .card li { line-height: 1.5; }
.card ul { padding-left: 20px; }
.card table { border-collapse: collapse; width: 100%; }
.card td, .card th { border-bottom: 1px solid #e5e5e5; padding: 6px 8px; text-align: left; vertical-align: top; }
